<h1><?= e($definition['title']) ?></h1>
<form method="get" class="admin-filters"><div class="field"><label for="q">Buscar por cliente<?= $key==='avaliacoes' ? ' ou livro' : '' ?></label><input type="search" id="q" name="q" value="<?= e($q) ?>" maxlength="100"></div><div class="field"><label for="status">Situação</label><select id="status" name="status"><option value="">Todas</option><?php foreach ($definition['states'] as $state): ?><option value="<?= e($state) ?>"<?= $state===$status?' selected':'' ?>><?= e(ucfirst($state)) ?></option><?php endforeach; ?></select></div><?php if (in_array($key,['pagamentos','devolucoes'],true)): ?><div class="field"><label for="pedido">Nº do pedido</label><input id="pedido" name="pedido" type="number" min="1" value="<?= e($orderId) ?>"></div><?php endif; ?><button class="btn">Filtrar</button></form>
<?php if (!$rows): ?><p class="empty">Nenhum registro encontrado.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Registro</th><th>Cliente</th><th>Data</th><th>Situação</th><th>Ação</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td data-label="Registro">nº <?= (int)$row['id'] ?><?php if (isset($row['subject_label'])): ?><br><?= e($row['subject_label']) ?><?php elseif (isset($row['order_id'])): ?><br>Pedido nº <?= (int)$row['order_id'] ?><?php endif; ?><?php if ($key==='pagamentos'): ?><br><?= e(money($row['amount'])) ?><?php endif; ?></td><td data-label="Cliente"><?= e($row['customer_name']) ?></td><td data-label="Data"><?= e(format_date($row['created_at'])) ?></td><td data-label="Situação"><?= e(ucfirst($row['status'])) ?></td><td><a class="btn btn-outline" href="<?= e(url('/admin/'.$key.'/'.(int)$row['id'])) ?>">Abrir</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?= render_template('admin/_pagination',compact('page','pages','total')+['path'=>'/admin/'.$key,'filters'=>['q'=>$q,'status'=>$status,'pedido'=>$orderId]]) ?>
<?php if ($key==='pagamentos'): ?><section class="section"><h2>Registrar tentativa de pagamento</h2><form method="post" class="card form-stack" action="<?= e(url('/admin/pagamentos')) ?>"><?= csrf_field() ?>
<div class="form-grid"><div class="field"><label for="order_id">Número do pedido</label><input id="order_id" name="order_id" type="number" min="1" value="<?= e($orderId) ?>" required></div><div class="field"><label for="amount">Valor em euros</label><input id="amount" name="amount" inputmode="decimal" required></div><div class="field"><label for="method">Forma</label><select id="method" name="method"><?php foreach (['pix'=>'Pix','cartao_credito'=>'Cartão de crédito','cartao_debito'=>'Cartão de débito','boleto'=>'Boleto','outro'=>'Outro'] as $value=>$label): ?><option value="<?= e($value) ?>"><?= e($label) ?></option><?php endforeach; ?></select></div><div class="field"><label for="installments">Parcelas</label><input id="installments" name="installments" type="number" min="1" max="24" value="1" required></div></div>
<div class="form-grid"><div class="field"><label for="gateway">Gateway</label><input id="gateway" name="gateway" maxlength="30" value="manual"></div><div class="field"><label for="gateway_id">Referência no gateway</label><input id="gateway_id" name="gateway_id" maxlength="100"></div></div>
<div class="field"><label for="pix_code">Código Pix</label><textarea id="pix_code" name="pix_code" rows="3" maxlength="5000"></textarea></div><div class="field"><label for="pix_expires_at">Validade do Pix</label><input type="datetime-local" id="pix_expires_at" name="pix_expires_at"></div><div class="field"><label for="gateway_response">Retorno do gateway (JSON, opcional)</label><textarea id="gateway_response" name="gateway_response" rows="3" maxlength="10000"></textarea></div><button class="btn">Registrar tentativa</button></form></section><?php endif; ?>
